import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        if (n >= 4 && m >= 4) {
            System.out.println(n * m - (n * m % 2));
        } else {
            int min = Math.min(n, m);
            int max = Math.max(n, m);
            if (min == 1) {
                int mod = max % 6;
                if (mod == 5) {
                    System.out.println((max / 6) * 6 + 4);
                } else if (mod == 4) {
                    System.out.println((max / 6) * 6 + 2);
                } else {
                    System.out.println((max / 6) * 6);
                }
            } else if (min == 2 && max == 7) {
                System.out.println(12);
            } else if ((min == 2 && max >= 4) || (min == 3 && max >= 4)) {
                System.out.println(n * m - (n * m % 2));
            } else {
                int[][] d = {
                    {0, 0, 0, 2, 4},
                    {0, 0, 4, 8, 10},
                    {0, 0, 8, 12, 14},
                    {0, 0, 0, 16, 20},
                    {0, 0, 0, 0, 24}
                };
                System.out.println(d[min - 1][max - 1]);
            }
        }
        sc.close();
    }
}
